b:includable.script:
function action(type) {
    const care = document.getElementById('care-selector').value;
    const status = document.getElementById('status-msg');
    const base = "Bertindaklah sebagai Pakar Perawatan Medis Profesional. Fokus pada " + care + ". Berikan analisis yang akurat, empati, dan berbasis bukti klinis. ";
    let prompt = "";

    if(type=="emergency") prompt = base + "Pilih secara acak 1 kondisi kegawatan pada perawatan paliatif, lalu berikan langkah penanganan cepat (poin-poin).";
    else if(type=="assess") prompt = base + "Berikan daftar alat penilaian klinis (assessment tool) yang paling tepat untuk pasien " + care + ".";
    else if(type=="pps") prompt = base + "Berikan pembahasan komprehensif mengenai Palliative Performance Scale (PPS v2) dari Victoria Hospice. Jelaskan setiap level, cara penilaian praktikal, berikan studi kasus, dan buatkan 5 soal ujian pilihan ganda untuk menguji pemahaman saya.";
    else if(type=="acp") prompt = base + "Berikan panduan cara memulai percakapan Advanced Care Planning (ACP) dengan pasien dan keluarga, serta elemen penting yang harus ada dalam dokumen legal/medis ACP.";
    else if(type=="guide") prompt = base + "Berikan protokol standar atau clinical guideline terbaru untuk " + care + ".";
    else if(type=="meds") prompt = base + "Fokus pada Manajemen Farmakologi. Pilih secara acak satu gejala fisik (nyeri hebat, mual, atau konstipasi) lalu berikan panduan dosis, titrasi, dan pilihan obat paliatif.";
    else if(type=="support") prompt = base + "Berikan teknik komunikasi empatik dan dukungan emosional untuk keluarga pasien " + care + ".";
    else if(type=="case") prompt = base + "Berikan satu skenario kasus nyata pada " + care + " dan minta saya untuk memberikan tindakan terbaik.";
    else if(type=="infinite") prompt = base + "Mode INFINITE DRILL: Berikan 1 soal studi kasus yang mencakup topik Emergency, Assessment, Guideline, Farmakologi, ACP, PPS v2, Dukungan Emosional, Terminal Care, atau Etika secara acak. Setelah saya jawab, berikan umpan balik dan berikan soal berikutnya secara terus-menerus.";
    else if(type=="terminal") prompt = base + "Fokus pada Terminal Hour Care. Berikan panduan penanganan fisik (seperti death rattle/sesak) dan dukungan spiritual.";
    else if(type=="ethics") prompt = base + "Berikan dilema etis yang sering terjadi pada " + care + " dan jelaskan cara mengambil keputusan yang bijak.";

    navigator.clipboard.writeText(prompt).then(function() {
        status.style.color = "#059669";
        status.innerHTML = "Instruksi disalin!Silakan paste di Gemini.";
        setTimeout(function() { 
            status.style.color = "#475569";
            status.innerHTML = "Silakan pilih modul,klik tombol di bawah ini untuk copy-paste di Gemini."; 
        }, 3000);
        window.open('https://gemini.google.com/', '_blank');
    });
}
